const lightbox=document.getElementById('galleryLightbox'), lightboxImage=document.getElementById('lightboxImage'), lightboxCaption=document.getElementById('lightboxCaption'), lightboxClose=document.getElementById('lightboxClose'); let lastGalleryTrigger=null;
const closeLightbox=()=>{if(!lightbox)return;lightbox.classList.remove('open');lightbox.setAttribute('aria-hidden','true');document.body.style.overflow='';lastGalleryTrigger?.focus();};
