function buildUpiUrl(amount, includeAmount=true){const params=new URLSearchParams({pa:UPI_ID,pn:UPI_NAME,cu:'INR',tn:'Donation - Shri Renuka Darbar'});if(includeAmount&&amount&&Number(amount)>0)params.set('am',Number(amount).toFixed(2));return `upi://pay?${params.toString()}`;}
function preparePayment(amount){const url=buildUpiUrl(amount,true);upiPayLinks.forEach(link=>{if(!link.id||!['googlePayBtn','phonePeBtn'].includes(link.id))link.href=url;});if(qrBox){qrBox.innerHTML='';if(window.QRCode){new QRCode(qrBox,{text:url,width:190,height:190,correctLevel:QRCode.CorrectLevel.M});if(qrAmountText)qrAmountText.textContent=`₹${Number(amount).toLocaleString('en-IN')} देणगीसाठी Scan & Pay`;}else qrBox.innerHTML='<span>QR तयार करण्यासाठी इंटरनेट कनेक्शन आवश्यक आहे.</span>';}}
function nextReceiptNumber(){const now=new Date(),fyStart=now.getMonth()>=3?now.getFullYear():now.getFullYear()-1,fyEnd=String(fyStart+1).slice(-2),key=`renukaReceiptSeq-${fyStart}-${fyEnd}`;const seq=Number(localStorage.getItem(key)||'0')+1;localStorage.setItem(key,String(seq));return `RD/${fyStart}-${fyEnd}/${String(seq).padStart(6,'0')}`;}

