const RECEIPT_LOGO_DATA='data:image/png;base64,';
function roundRect(ctx,x,y,w,h,r){const rr=Math.min(r,w/2,h/2);ctx.beginPath();ctx.moveTo(x+rr,y);ctx.arcTo(x+w,y,x+w,y+h,rr);ctx.arcTo(x+w,y+h,x,y+h,rr);ctx.arcTo(x,y+h,x,y,rr);ctx.arcTo(x,y,x+w,y,rr);ctx.closePath();}
function drawWrapped(ctx,text,x,y,maxWidth,lineHeight,maxLines=4){const words=String(text||'').split(/\s+/);let line='',lines=[];for(const word of words){const test=line?line+' '+word:word;if(ctx.measureText(test).width<=maxWidth)line=test;else{if(line)lines.push(line);line=word;}}if(line)lines.push(line);lines=lines.slice(0,maxLines);lines.forEach((l,i)=>ctx.fillText(l,x,y+i*lineHeight));return y+lines.length*lineHeight;}
function loadReceiptLogo(){return new Promise(resolve=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>resolve(null);img.src=RECEIPT_LOGO_DATA;});}
async function renderReceiptCanvas(){
  // A4 portrait receipt matching the supplied printed-receipt reference.
  const W=1240,H=1400,canvas=document.createElement('canvas');canvas.width=W;canvas.height=H;
  const ctx=canvas.getContext('2d',{alpha:false});if(!ctx)throw new Error('Canvas is not supported');
  ctx.fillStyle='#ffffff';ctx.fillRect(0,0,W,H);

  // Thin printed-paper border.
  ctx.strokeStyle='#b8b8b8';ctx.lineWidth=2;ctx.strokeRect(8,8,W-16,H-16);

  const logo=await loadReceiptLogo();
  // Receipt header: logo on the left, trust/temple name beside it (better on mobile PDF view).
  const headerTextX=690;
  if(logo){
    const maxW=155,maxH=135;
    const scale=Math.min(maxW/logo.naturalWidth,maxH/logo.naturalHeight);
    const lw=logo.naturalWidth*scale,lh=logo.naturalHeight*scale;
    ctx.drawImage(logo,70,35,lw,lh);
  }
  ctx.textAlign='center';
  ctx.fillStyle='#7b4a37';
  ctx.font='bold 20px Noto Sans Devanagari, Noto Sans, Arial';
  ctx.fillText('प. पू. माता प्रेमानंदीनाथ महाराज पब्लिक चॅरिटेबल ट्रस्ट संचालित',headerTextX,82);
  ctx.fillStyle='#68151b';
  ctx.font='bold 34px Noto Sans Devanagari, Noto Sans, Arial';
  ctx.fillText('श्री क्षेत्र रेणुका दरबार, सद्गुरू शक्तिपीठ',headerTextX,126);
  ctx.fillText('काचमंदीर सोनई',headerTextX,168);
  ctx.fillStyle='#8a641f';
  ctx.font='bold 18px Noto Sans Devanagari, Noto Sans, Arial';
  ctx.fillText('॥ जय जगदंब ॥',W/2,238);
  ctx.fillText('देणगी पावती',W/2,276);
  ctx.textAlign='left';

  ctx.strokeStyle='#b98a42';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(42,292);ctx.lineTo(W-42,292);ctx.stroke();

  const method=document.getElementById('paymentMethod')?.value||'';
  const txn=document.getElementById('transactionId')?.value.trim()||'';
  const now=new Date();
  const date=new Intl.DateTimeFormat('mr-IN',{dateStyle:'long',timeStyle:'short'}).format(now);
  const receiptNo=donorData.receiptNo;

  // Two-column layout matching the reference print.
  const leftX=42,rightX=625,labelGap=145,colW=535,rowH=72;
  let y=380;
  const rows=[
    ['पावती क्र.',receiptNo,'दिनांक',date],
    ['देणगीदार',donorData.name,'मोबाईल',donorData.mobile],
    ['ई-मेल',donorData.email,'पेमेंट',method],
    ['रक्कम',`₹${Number(donorData.amount).toLocaleString('en-IN')}`,'स्थिती','पेमेंट पूर्ण झाले']
  ];
  for(const [ll,lv,rl,rv] of rows){
    ctx.textAlign='left';
    ctx.fillStyle='#2f2520';ctx.font='bold 21px Noto Sans Devanagari, Noto Sans, Arial';ctx.fillText(ll,leftX,y);
    ctx.font='21px Noto Sans Devanagari, Noto Sans, Arial';drawWrapped(ctx,String(lv),leftX+labelGap,y,colW-labelGap,28,2);
    ctx.fillStyle='#2f2520';ctx.font='bold 21px Noto Sans Devanagari, Noto Sans, Arial';ctx.fillText(rl,rightX,y);
    ctx.font='21px Noto Sans Devanagari, Noto Sans, Arial';drawWrapped(ctx,String(rv),rightX+labelGap,y,colW-labelGap,28,2);
    ctx.strokeStyle='#d8b982';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(leftX,y+27);ctx.lineTo(leftX+colW-15,y+27);ctx.stroke();
    ctx.beginPath();ctx.moveTo(rightX,y+27);ctx.lineTo(rightX+colW-15,y+27);ctx.stroke();
    y+=rowH;
  }

  // Transaction and address span the full receipt width.
  ctx.textAlign='left';
  ctx.fillStyle='#2f2520';ctx.font='bold 21px Noto Sans Devanagari, Noto Sans, Arial';ctx.fillText('व्यवहार क्रमांक / UTR:',42,y);
  ctx.font='21px Noto Sans Devanagari, Noto Sans, Arial';ctx.fillText(String(txn),225,y);
  ctx.strokeStyle='#d8b982';ctx.beginPath();ctx.moveTo(42,y+27);ctx.lineTo(W-42,y+27);ctx.stroke();y+=72;

  const address=`${donorData.address}, ${donorData.city} - ${donorData.pin}`;
  ctx.fillStyle='#2f2520';ctx.font='bold 21px Noto Sans Devanagari, Noto Sans, Arial';ctx.fillText('पत्ता:',42,y);
  ctx.font='21px Noto Sans Devanagari, Noto Sans, Arial';
  drawWrapped(ctx,address,115,y,W-157,29,2);
  ctx.strokeStyle='#d8b982';ctx.beginPath();ctx.moveTo(42,y+48);ctx.lineTo(W-42,y+48);ctx.stroke();

  // Short acknowledgement only; no pending-verification wording.
  y+=110;
  ctx.fillStyle='#2f2520';ctx.font='bold 20px Noto Sans Devanagari, Noto Sans, Arial';
  ctx.fillText('सूचना:',42,y);
  ctx.font='20px Noto Sans Devanagari, Noto Sans, Arial';
  const note='ही पावती देणगीदाराने दिलेल्या व्यवहार क्रमांक / UTR संदर्भावर आधारित आहे.';
  drawWrapped(ctx,note,115,y,W-157,29,2);
  ctx.strokeStyle='#d8b982';ctx.beginPath();ctx.moveTo(42,y+55);ctx.lineTo(W-42,y+55);ctx.stroke();

  y+=125;
  ctx.textAlign='center';ctx.fillStyle='#68151b';
  ctx.font='bold 24px Noto Sans Devanagari, Noto Sans, Arial';
  ctx.fillText('आपल्या देणगीबद्दल मनःपूर्वक धन्यवाद.',W/2,y);
  ctx.font='bold 22px Noto Sans Devanagari, Noto Sans, Arial';
  ctx.fillText('श्री क्षेत्र रेणुका दरबारचा प्रसाद आपण दिलेल्या पत्त्यावर घरपोच पाठविण्यात येईल.',W/2,y+42);

  // Bottom legal note, matching the supplied receipt.
  ctx.textAlign='left';ctx.fillStyle='#3f3833';ctx.font='16px Noto Sans Devanagari, Noto Sans, Arial';
  const legal='कर सवलत सूचना: हा दस्तऐवज स्वतःहून आयकर कलम 80G अंतर्गत कर-सवलत प्रमाणपत्र नाही. लागू असल्यास अधिकृत कर-सवलत प्रमाणपत्र संस्थेच्या वैध नोंदणी व लागू आयकर प्रक्रियेनुसार स्वतंत्रपणे दिले जाईल.';
  drawWrapped(ctx,legal,42,H-100,W-84,24,4);
  return canvas;
}
function canvasToBlob(canvas,type,quality){
  return new Promise((resolve,reject)=>{
    try{
      if(canvas.toBlob){
        canvas.toBlob(blob=>blob?resolve(blob):reject(new Error('Canvas export returned empty blob')),type,quality);
      }else{
        const dataUrl=canvas.toDataURL(type,quality);
        resolve(dataUrlToBlob(dataUrl));
      }
    }catch(err){reject(err);}
  });
}
function dataUrlToBlob(dataUrl){
  const parts=dataUrl.split(',');
  const mime=(parts[0].match(/data:([^;]+)/)||[])[1]||'application/octet-stream';
  const bin=atob(parts[1]||'');
  const bytes=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
  return new Blob([bytes],{type:mime});
}
function pdfBlobFromJpegDataUrl(dataUrl){
  const jpeg=dataUrlToBlob(dataUrl);
  const imgBytes=new Uint8Array(jpeg.size);
  // Blob.arrayBuffer() is async, so this function is replaced by the async builder below.
  return makeSinglePagePdf(dataUrl);
}
async function makeSinglePagePdf(dataUrl){
  const parts=dataUrl.split(',');
  const bin=atob(parts[1]||'');
  const imgLen=bin.length;
  const imageBytes=new Uint8Array(imgLen);
  for(let i=0;i<imgLen;i++)imageBytes[i]=bin.charCodeAt(i);
  const enc=new TextEncoder();
  const header=enc.encode('%PDF-1.4\n%\xFF\xFF\xFF\xFF\n');
  const objects=[];
  objects.push(enc.encode('1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n'));
  objects.push(enc.encode('2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n'));
  objects.push(enc.encode('3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 672.10] /Resources << /XObject << /Im0 5 0 R >> >> /Contents 4 0 R >>\nendobj\n'));
  const content='q\n595.28 0 0 672.10 0 0 cm\n/Im0 Do\nQ\n';
  objects.push(enc.encode(`4 0 obj\n<< /Length ${content.length} >>\nstream\n${content}endstream\nendobj\n`));
  const imagePrefix=enc.encode(`5 0 obj\n<< /Type /XObject /Subtype /Image /Width 1240 /Height 1400 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${imgLen} >>\nstream\n`);
  const imageSuffix=enc.encode('\nendstream\nendobj\n');
  const chunks=[header];
  const offsets=[0];
  let position=header.length;
  for(const obj of objects){offsets.push(position);chunks.push(obj);position+=obj.length;}
  offsets.push(position);chunks.push(imagePrefix);position+=imagePrefix.length;chunks.push(imageBytes);position+=imageBytes.length;chunks.push(imageSuffix);position+=imageSuffix.length;
  const xrefStart=position;
  let xref=`xref\n0 6\n0000000000 65535 f \n`;
  for(let i=1;i<=5;i++)xref+=String(offsets[i]).padStart(10,'0')+' 00000 n \n';
  xref+=`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`;
  chunks.push(enc.encode(xref));
  return new Blob(chunks,{type:'application/pdf'});
}
function downloadBlob(blob,filename){
  if(!blob||!blob.size)throw new Error('Empty download file');
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');
  a.href=url;a.download=filename;a.rel='noopener';a.style.display='none';
  document.body.appendChild(a);
  a.click();
  setTimeout(()=>{a.remove();URL.revokeObjectURL(url);},30000);
}

let receiptBusy=false;
function receiptFileName(ext){return `${String(donorData?.receiptNo||'renuka-darbar-receipt').replace(/[^a-zA-Z0-9_-]+/g,'-')}.${ext}`;}
async function buildReceiptFiles(){
  const canvas=await renderReceiptCanvas();
  const png=await canvasToBlob(canvas,'image/png');
  if(!png||!png.size)throw new Error('PNG export failed');
  let jpg;
  try{jpg=canvas.toDataURL('image/jpeg',0.92);}catch(e){throw new Error('JPEG export failed: '+e.message);}
  const pdf=await makeSinglePagePdf(jpg);
  if(!pdf||!pdf.size)throw new Error('PDF export failed');
  return {png,pdf};
}
function setReceiptDownload(button,blob,filename){
  button.disabled=false;
  button.onclick=()=>{
    try{
      const url=URL.createObjectURL(blob);
      const a=document.createElement('a');a.href=url;a.download=filename;a.target='_blank';a.rel='noopener';
      document.body.appendChild(a);a.click();a.remove();
      setTimeout(()=>URL.revokeObjectURL(url),60000);
    }catch(e){
      console.error('Download failed:',e);
      const url=URL.createObjectURL(blob);window.open(url,'_blank','noopener');
    }
  };
}
async function createReceipt(){
  if(!donorData||receiptBusy)return;
  const method=document.getElementById('paymentMethod'),txn=document.getElementById('transactionId');
  if(!method.value){method.focus();method.reportValidity();return;}
  if(!txn.value.trim()){txn.focus();txn.reportValidity();return;}
  const utr=txn.value.trim().replace(/\s+/g,'').toUpperCase();
  const existing=JSON.parse(localStorage.getItem('renukaDarbarReceiptUTRs_v2')||'{}');
  if(existing[utr]){alert(`हा Transaction ID / UTR आधीच पावती क्र. ${existing[utr]} साठी वापरला आहे.`);return;}
  receiptBusy=true;
  const now=new Date();
  donorData.receiptNo=nextReceiptNumber();
  const date=new Intl.DateTimeFormat('mr-IN',{dateStyle:'long',timeStyle:'short'}).format(now);
  receiptDetails.innerHTML=`<div class="receipt-data receipt-reference-layout"><div class="receipt-row"><p><b>पावती क्र.:</b> ${esc(donorData.receiptNo)}</p><p><b>दिनांक:</b> ${esc(date)}</p></div><div class="receipt-row"><p><b>देणगीदार:</b> ${esc(donorData.name)}</p><p><b>मोबाईल:</b> ${esc(donorData.mobile)}</p></div><div class="receipt-row"><p><b>ई-मेल:</b> ${esc(donorData.email)}</p><p><b>पेमेंट:</b> ${esc(method.value)}</p></div><div class="receipt-row"><p><b>रक्कम:</b> ₹${esc(Number(donorData.amount).toLocaleString('en-IN'))}</p><p><b>स्थिती:</b> पेमेंट पूर्ण झाले</p></div><p class="wide"><b>व्यवहार क्रमांक / UTR:</b> ${esc(utr)}</p><p class="wide"><b>पत्ता:</b> ${esc(donorData.address)}, ${esc(donorData.city)} - ${esc(donorData.pin)}</p><p class="receipt-note"><b>सूचना:</b> ही पावती देणगीदाराने दिलेल्या व्यवहार क्रमांक / UTR संदर्भावर आधारित आहे.</p></div>`;
  donationReceipt.hidden=false;donationReceipt.scrollIntoView({behavior:'smooth',block:'start'});
  const pdfBtn=document.getElementById('downloadReceiptPdf'),imgBtn=document.getElementById('downloadReceiptImage');
  pdfBtn.disabled=true;imgBtn.disabled=true;pdfBtn.textContent='पावती तयार होत आहे…';imgBtn.textContent='पावती तयार होत आहे…';const generationMsg=document.getElementById('receiptGenerationError');if(generationMsg)generationMsg.textContent='';
  try{
    const files=await buildReceiptFiles();
    setReceiptDownload(pdfBtn,files.pdf,receiptFileName('pdf'));
    setReceiptDownload(imgBtn,files.png,receiptFileName('png'));
    const saveResult=await rdSaveDonationRecord(utr,method.value);if(!saveResult.ok)throw new Error(saveResult.reason||'Google Sheet save failed');existing[utr]=donorData.receiptNo;localStorage.setItem('renukaDarbarReceiptUTRs_v2',JSON.stringify(existing));
    pdfBtn.textContent='PDF पावती डाउनलोड करा';imgBtn.textContent='पावती फोटो डाउनलोड करा';const generationMsg2=document.getElementById('receiptGenerationError');if(generationMsg2)generationMsg2.textContent='';
  }catch(err){
    console.error('Receipt generation failed:',err);
    pdfBtn.disabled=false;imgBtn.disabled=false;
    pdfBtn.textContent='पावती तयार करा';imgBtn.textContent='पावती फोटो तयार करा';
    const msg=document.getElementById('receiptGenerationError');
    if(msg)msg.textContent='पावती तयार करण्यात अडचण आली. कृपया पुन्हा “पावती तयार करा” दाबा.';
  }finally{receiptBusy=false;}
}
